
"""Generate annotated PCB images and inspection reports."""

from __future__ import annotations

import json
from collections import Counter
from dataclasses import dataclass
from datetime import datetime
from pathlib import Path

from PIL import Image, ImageDraw, ImageFont

from config import (
    SEVERITY,
    ANNOTATED_DIR,
    REPORTS_DIR,
)

from decision import DecisionResult


@dataclass(frozen=True)
class ReportPaths:
    """Paths generated by the reporting module."""

    annotated_image: Path
    json_report: Path


# Colors for visual inspection
COLORS = {
    "FAIL": (220, 50, 50),
    "REVIEW": (240, 160, 30),
    "PASS": (40, 170, 90),
}


def serialize_detection(detection):
    """Convert a Detection object into JSON-compatible data."""

    return {
        "class_name": detection.class_name,
        "confidence": round(detection.confidence, 4),
        "severity": SEVERITY[detection.class_name],
        "bounding_box": {
            "x1": round(detection.xyxy[0], 2),
            "y1": round(detection.xyxy[1], 2),
            "x2": round(detection.xyxy[2], 2),
            "y2": round(detection.xyxy[3], 2),
        },
        "area": round(detection.area, 2),
    }


def annotate_image(
    image_path: Path,
    result: DecisionResult,
    output_path: Path,
) -> None:
    """Draw confirmed defects and review candidates on a PCB image."""

    with Image.open(image_path) as source:
        image = source.convert("RGB")

    draw = ImageDraw.Draw(image)
    font = ImageFont.load_default()

    # Confirmed defects
    for detection in result.detections:
        x1, y1, x2, y2 = detection.xyxy

        color = COLORS["FAIL"]

        draw.rectangle(
            (x1, y1, x2, y2),
            outline=color,
            width=3,
        )

        label = (
            f"{detection.class_name} "
            f"{detection.confidence:.2f}"
        )

        draw.text(
            (x1, max(0, y1 - 14)),
            label,
            fill=color,
            font=font,
        )

    # Borderline candidates
    for detection in result.review_candidates:
        x1, y1, x2, y2 = detection.xyxy

        color = COLORS["REVIEW"]

        draw.rectangle(
            (x1, y1, x2, y2),
            outline=color,
            width=3,
        )

        label = (
            f"REVIEW: {detection.class_name} "
            f"{detection.confidence:.2f}"
        )

        draw.text(
            (x1, max(0, y1 - 14)),
            label,
            fill=color,
            font=font,
        )

    output_path.parent.mkdir(parents=True, exist_ok=True)
    image.save(output_path, format="PNG")


def generate_report(
    image_path: str | Path,
    result: DecisionResult,
    board_id: str = "unknown",
) -> ReportPaths:
    """
    Generate an annotated image and JSON inspection report.

    The original PCB image is never modified.
    """

    image_path = Path(image_path)

    if not image_path.is_file():
        raise FileNotFoundError(
            f"Inspection image not found: {image_path}"
        )

    ANNOTATED_DIR.mkdir(parents=True, exist_ok=True)
    REPORTS_DIR.mkdir(parents=True, exist_ok=True)

    timestamp = datetime.now().strftime("%Y%m%d_%H%M%S_%f")

    filename = f"{board_id}_{timestamp}"

    annotated_path = ANNOTATED_DIR / f"{filename}.png"
    json_path = REPORTS_DIR / f"{filename}.json"

    # 1. Generate annotated image
    annotate_image(
        image_path=image_path,
        result=result,
        output_path=annotated_path,
    )

    # 2. Calculate defect statistics
    defect_counts = Counter(
        detection.class_name
        for detection in result.detections
    )

    review_counts = Counter(
        detection.class_name
        for detection in result.review_candidates
    )

    # 3. Build report
    report = {
        "board_id": board_id,
        "timestamp": datetime.now().isoformat(timespec="seconds"),
        "source_image": str(image_path.resolve()),

        "inspection": {
            "status": result.status,
            "inspection_complete": result.inspection_complete,
            "total_defects": result.total_defects,
            "total_review_candidates": result.total_review_candidates,
        },

        "summary": {
            "confirmed_defects": dict(defect_counts),
            "review_candidates": dict(review_counts),
        },

        "defects": [
            serialize_detection(d)
            for d in result.detections
        ],

        "review_candidates": [
            serialize_detection(d)
            for d in result.review_candidates
        ],

        "reasons": result.reasons,

        "artifacts": {
            "annotated_image": str(annotated_path.resolve()),
        },
    }

    # 4. Save JSON report
    with open(json_path, "w", encoding="utf-8") as file:
        json.dump(report, file, indent=4)

    return ReportPaths(
        annotated_image=annotated_path,
        json_report=json_path,
    )
